async function jsonApi(url:string, init?:RequestInit) {
  const response = await fetch(url, { ...init, headers: { ...(init?.body instanceof FormData ? {} : { "Content-Type":"application/json" }), ...init?.headers } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    if (response.status===413) throw new Error("Zdjęcia są zbyt duże. Usuń jedno zdjęcie lub wybierz mniejsze pliki i spróbuj ponownie.");
    throw new Error(data.error || "Wystąpił błąd");
  }
  return data;
}

async function optimizeUploadImage(file:File) {
  if (!file.type.startsWith("image/")) return file;
  try {
    const bitmap=await createImageBitmap(file,{imageOrientation:"from-image"});
    const maxSide=1920;const initialScale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));
    let width=Math.max(1,Math.round(bitmap.width*initialScale));let height=Math.max(1,Math.round(bitmap.height*initialScale));
    let quality=.82;let best:Blob|null=null;
    for(let attempt=0;attempt<5;attempt++){const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;const context=canvas.getContext("2d");if(!context)break;context.drawImage(bitmap,0,0,width,height);const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,"image/jpeg",quality));if(blob&&(!best||blob.size<best.size))best=blob;if(blob&&blob.size<=1.5*1024*1024)break;width=Math.max(960,Math.round(width*.82));height=Math.max(960,Math.round(height*.82));quality=Math.max(.58,quality-.07)}
    bitmap.close();if(!best||best.size>=file.size)return file;
    return new File([best],file.name.replace(/\.[^.]+$/,"")+".jpg",{type:"image/jpeg",lastModified:file.lastModified});
  } catch { return file }
}

async function uploadVisitImage(file:File) {
  const form=new FormData();form.append("file",file);
  const data=await jsonApi("/api/uploads",{method:"POST",body:form});
  return String(data.upload.id);
}

